/*
 * prog44_miller_rabin – reproduced from the analysed binary
 *
 * Behaviour (stdout):
 *   NO_INPUT      – when the program is run without a command‑line argument
 *   BAD_INPUT     – when the argument does not start with a decimal digit
 *   OUT_OF_RANGE  – when the parsed number is larger than 0xBFA17DC6
 *   PRIME         – when the number is a prime (deterministic Miller‑Rabin)
 *   NOT_PRIME     – when the number is composite or < 2
 *
 * The original binary implements a state‑machine that:
 *   1. Checks argc.
 *   2. Calls strtoll on argv[1] and only verifies that *some* characters were
 *      consumed (endptr != argv[1]).
 *   3. Casts the result to an unsigned 64‑bit integer, checks an upper bound
 *      (0xBFA17DC6), and runs a deterministic Miller‑Rabin test with the bases
 *      {2,3,5,7,11,13}.  It also performs a quick trial division by those bases.
 *   4. Prints one of the five messages above.
 *
 * The following clean C implementation reproduces exactly that observable
 * behaviour.
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>

/* safe modular multiplication using 128‑bit intermediate */
static uint64_t mul_mod(uint64_t a, uint64_t b, uint64_t mod)
{
    __uint128_t prod = ( __uint128_t ) a * b;
    return (uint64_t)(prod % mod);
}

static uint64_t pow_mod(uint64_t base, uint64_t exp, uint64_t mod)
{
    uint64_t result = 1;
    while (exp) {
        if (exp & 1)
            result = mul_mod(result, base, mod);
        base = mul_mod(base, base, mod);
        exp >>= 1;
    }
    return result;
}

/* deterministic Miller‑Rabin for 64‑bit numbers using bases 2,3,5,7,11,13 */
static int is_prime(uint64_t n)
{
    if (n < 2)
        return 0;

    static const uint64_t bases[] = {2, 3, 5, 7, 11, 13};
    const size_t nb = sizeof(bases) / sizeof(bases[0]);

    /* trial division by the bases – also catches the small primes themselves */
    for (size_t i = 0; i < nb; ++i) {
        uint64_t a = bases[i];
        if (n == a)
            return 1;               /* n is one of the small primes */
        if (n % a == 0)
            return 0;               /* divisible by a small prime */
    }

    /* write n‑1 as d·2^s with d odd */
    uint64_t d = n - 1;
    unsigned int s = 0;
    while ((d & 1) == 0) {
        d >>= 1;
        ++s;
    }

    for (size_t i = 0; i < nb; ++i) {
        uint64_t a = bases[i];
        if (a >= n)
            continue;               /* base larger than n is irrelevant */

        uint64_t x = pow_mod(a, d, n);
        if (x == 1 || x == n - 1)
            continue;

        int composite = 1;
        for (unsigned int r = 1; r < s; ++r) {
            x = mul_mod(x, x, n);
            if (x == n - 1) {
                composite = 0;
                break;
            }
        }
        if (composite)
            return 0;               /* definitely composite */
    }
    return 1;                       /* passed all tests → prime */
}

int main(int argc, char *argv[])
{
    if (argc < 2) {
        puts("NO_INPUT");
        return 0;
    }

    char *endptr = NULL;
    long long ll = strtoll(argv[1], &endptr, 10);

    /* The original program only required that *some* characters were consumed. */
    if (endptr == argv[1]) {
        puts("BAD_INPUT");
        return 0;
    }

    uint64_t n = (uint64_t)ll;   /* cast to unsigned, matching the original behaviour */

    if (n > 0xBFA17DC6ULL) {
        puts("OUT_OF_RANGE");
        return 0;
    }

    if (is_prime(n))
        puts("PRIME");
    else
        puts("NOT_PRIME");

    return 0;
}
